$map = [ordered]@{
  'classic' = $classic
  'gold'    = $gold
  'sport'   = $sport
  'minimal' = $minimal
  'rose'    = $rose
  'chrono'  = $chrono
}

$classes = @('img-wrap', 'hero-thumb-circle', 'why-image', 'exp-image')
$count = 0
foreach ($key in $map.Keys) {
  $val = $map[$key]
  foreach ($cls in $classes) {
    $find = '<div class="' + $cls + '" data-watch="' + $key + '"></div>'
    $repl = '<div class="' + $cls + '" data-watch="' + $key + '">' + $val + '</div>'
    if ($c.Contains($find)) {
      $c = $c.Replace($find, $repl)
      $count++
    }
  }
}

[System.IO.File]::WriteAllText($f, $c, (New-Object System.Text.UTF8Encoding $false))
Write-Host "Replaced: $count"
Write-Host "Remaining empty: $(([regex]::Matches($c, 'data-watch="[^"]+"></div>')).Count)"
Write-Host "Final size: $((Get-Item $f).Length)"
